import{_ as o,c as r,o as i,a5 as t}from"./chunks/framework.CUJoMJm2.js";const h=JSON.parse('{"title":"RPC Behavior","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/rpc/behavior.md","filePath":"protocols/rpc/behavior.md","lastUpdated":0}'),a={name:"protocols/rpc/behavior.md"};function c(s,e,n,l,d,u){return i(),r("div",null,[...e[0]||(e[0]=[t('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/rpc/behavior.md for this page in Markdown format</div><h1 id="rpc-behavior" tabindex="-1">RPC Behavior <a class="header-anchor" href="#rpc-behavior" aria-label="Permalink to “RPC Behavior”">​</a></h1><blockquote><p><strong>Authority</strong>: Primary (Normative)<br><strong>Purpose</strong>: Request/response semantics, timeouts, correlation, and retry guidance.</p></blockquote><h2 id="request-response-lifecycle" tabindex="-1">Request/Response Lifecycle <a class="header-anchor" href="#request-response-lifecycle" aria-label="Permalink to “Request/Response Lifecycle”">​</a></h2><ol><li>Client sends <code>RpcRequest</code> with unique <code>cid</code> (correlation ID)</li><li>Server processes request</li><li>Server sends <code>RpcSuccess</code> or <code>RpcError</code> with matching <code>cid</code></li></ol><h2 id="correlation" tabindex="-1">Correlation <a class="header-anchor" href="#correlation" aria-label="Permalink to “Correlation”">​</a></h2><p>RPC correlation uses <code>cid</code> (correlation ID), not SBP <code>frameId</code>:</p><ul><li><code>cid</code> in requests is the sending frame&#39;s <code>frameId</code></li><li><code>cid</code> in responses matches the original request&#39;s <code>cid</code></li><li>Runtime matches on <code>cid</code>, not <code>frameId</code></li></ul><p>This enables relays, proxies, and fan-out without wire format changes. See ADR-010.</p><h2 id="timeouts" tabindex="-1">Timeouts <a class="header-anchor" href="#timeouts" aria-label="Permalink to “Timeouts”">​</a></h2><p>Implementations SHOULD:</p><ul><li>Set request timeout of 30 seconds by default</li><li>Allow per-method timeout configuration</li><li>Return <code>RpcError</code> with code 1001 (Timeout) on expiry</li></ul><p>Implementations MUST:</p><ul><li>Not assume responses arrive in request order</li><li>Handle responses after timeout gracefully (discard)</li></ul><h2 id="retry-guidance" tabindex="-1">Retry Guidance <a class="header-anchor" href="#retry-guidance" aria-label="Permalink to “Retry Guidance”">​</a></h2><p>Implementations MAY retry failed requests:</p><ul><li>On transport errors (not on application errors)</li><li>With exponential backoff (recommended: 1s, 2s, 4s, max 30s)</li><li>With jitter to avoid thundering herd</li></ul><p>Implementations MUST NOT retry:</p><ul><li>After receiving <code>RpcError</code> (server explicitly rejected)</li><li>Without new <code>cid</code> (would confuse correlation)</li></ul><h2 id="concurrent-requests" tabindex="-1">Concurrent Requests <a class="header-anchor" href="#concurrent-requests" aria-label="Permalink to “Concurrent Requests”">​</a></h2><p>Multiple requests MAY be in flight simultaneously:</p><ul><li>Each request has unique <code>cid</code></li><li>Responses may arrive out of order</li><li>Implementations SHOULD track pending requests by <code>cid</code></li></ul><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to “Notifications”">​</a></h2><p><code>RpcNotification</code> (type <code>&quot;N&quot;</code>) is fire-and-forget:</p><ul><li>No <code>cid</code> (no correlation)</li><li>No response expected</li><li>No delivery guarantee beyond transport layer</li></ul>',25)])])}const m=o(a,[["render",c]]);export{h as __pageData,m as default};
